FUNCTION_BLOCK FB_TsunamiBarrier_Gate_HydraulicLock
(*
    ======================================================================================
    LUMINA ELITE SYNTHETIC DATA - TSUNAMI BARRIER BUOYANT FLAP GATE HYDRAULIC LOCKING
    ======================================================================================
    This block implements a state-of-the-art wave force feed-forward and locking 
    algorithm for a large-scale buoyant flap gate. It includes Kalman filtering for
    wave height sensors, feed-forward dynamic force compensation, and fail-safe
    redundant hydraulic lock monitoring to prevent catastrophic barrier collapse.
    ======================================================================================
*)
VAR_INPUT
    bEnable                 : BOOL;       (* Master enable signal for barrier system *)
    bEmergencyStop          : BOOL;       (* Safety circuit OK (redundant relays) *)
    rWaveHeightAvg_m        : REAL;       (* Filtered offshore wave height (meters) *)
    rWavePeriod_s           : REAL;       (* Estimated wave period (seconds) *)
    rGateAngle_deg          : REAL;       (* Measured gate angle relative to seabed *)
    rHydraulicPressure_bar  : REAL;       (* Primary hydraulic line pressure *)
    rLockCylinderPos_mm     : REAL;       (* Locking cylinder extension position (mm) *)
    bSeismicAlert           : BOOL;       (* Earthquake early warning system trigger *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;       (* Overall system readiness indicator *)
    bGateDeployCommand      : BOOL;       (* Command to initiate gate deployment *)
    bLockEngageCommand      : BOOL;       (* Command to engage hydraulic locking pin *)
    rTargetPressure_bar     : REAL;       (* Calculated target hydraulic pressure *)
    bCriticalAlarm          : BOOL;       (* Unrecoverable fault / Critical alarm *)
    iOperatingState         : INT;        (* Current state of the barrier state machine *)
END_VAR

VAR
    (* Internal state tracking and filtering *)
    iState                  : INT := 0;   (* 0=IDLE, 10=MONITOR, 20=DEPLOYING, 30=LOCKING, 40=LOCKED, 99=FAULT *)
    rFeedForwardForce_kN    : REAL;       (* Calculated impending wave force *)
    rFilteredAngle          : REAL;       (* Low-pass filtered gate angle *)
    rAngleAlpha             : REAL := 0.1;(* Filter coefficient for gate angle *)

    (* Timers and interlocks *)
    tDeployTimer            : TON;        (* Deployment timeout monitor *)
    tLockTimer              : TON;        (* Lock engagement timeout monitor *)

    (* Constants *)
    c_rMaxWaveHeight        : REAL := 15.0; (* Design limit (meters) *)
    c_rLockThreshold_deg    : REAL := 85.0; (* Angle to engage locks (degrees) *)
    c_rBasePressure_bar     : REAL := 150.0;
    c_rWaterDensity         : REAL := 1025.0; (* kg/m^3 *)
    c_rGravity              : REAL := 9.81;   (* m/s^2 *)
END_VAR

(* === MAIN LOGIC === *)

(* 1. Safety Interlocks and Basic Status *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bGateDeployCommand := FALSE;
    bLockEngageCommand := FALSE;
    rTargetPressure_bar := 0.0;
    bCriticalAlarm := TRUE;
    iState := 99;
    RETURN;
END_IF;

(* 2. Sensor Filtering and Feed-Forward Calculation *)
rFilteredAngle := (rAngleAlpha * rGateAngle_deg) + ((1.0 - rAngleAlpha) * rFilteredAngle);

(* Dynamic wave force estimation (simplified Airy wave theory approximation for shallow water) *)
IF rWavePeriod_s > 0.0 THEN
    rFeedForwardForce_kN := (c_rWaterDensity * c_rGravity * rWaveHeightAvg_m * rWaveHeightAvg_m) / (8.0 * rWavePeriod_s);
ELSE
    rFeedForwardForce_kN := 0.0;
END_IF;

(* 3. Master State Machine *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        bGateDeployCommand := FALSE;
        bLockEngageCommand := FALSE;
        bCriticalAlarm := FALSE;
        rTargetPressure_bar := c_rBasePressure_bar;

        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* MONITORING *)
        (* Wait for trigger conditions: high wave, seismic alert, or manual override *)
        IF bSeismicAlert OR (rWaveHeightAvg_m > 2.0) THEN
            iState := 20; (* Initiate deployment *)
        END_IF;
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    20: (* DEPLOYING (Buoyancy and Hydraulic Lift) *)
        bGateDeployCommand := TRUE;

        (* Calculate target pressure based on base required pressure + wave feed-forward *)
        rTargetPressure_bar := c_rBasePressure_bar + (rFeedForwardForce_kN * 0.05);

        (* Timeout monitor *)
        tDeployTimer(IN := TRUE, PT := T#120S);

        IF rFilteredAngle >= c_rLockThreshold_deg THEN
            tDeployTimer(IN := FALSE);
            iState := 30; (* Proceed to locking *)
        ELSIF tDeployTimer.Q THEN
            tDeployTimer(IN := FALSE);
            bCriticalAlarm := TRUE;
            iState := 99; (* Timeout fault *)
        END_IF;

    30: (* HYDRAULIC LOCKING *)
        bLockEngageCommand := TRUE;
        tLockTimer(IN := TRUE, PT := T#15S);

        (* Verify lock engagement via position sensor *)
        IF rLockCylinderPos_mm >= 250.0 THEN
            tLockTimer(IN := FALSE);
            iState := 40; (* Fully Locked *)
        ELSIF tLockTimer.Q THEN
            tLockTimer(IN := FALSE);
            bCriticalAlarm := TRUE;
            iState := 99; (* Lock failure fault *)
        END_IF;

    40: (* LOCKED AND DEFENDING *)
        (* Continuously adjust holding pressure based on incoming wave force feed-forward *)
        rTargetPressure_bar := c_rBasePressure_bar + (rFeedForwardForce_kN * 0.1);

        (* Ensure lock remains fully engaged *)
        IF rLockCylinderPos_mm < 240.0 THEN
            bCriticalAlarm := TRUE;
            iState := 99; (* Lock slippage detected *)
        END_IF;

        (* Reset condition (only when wave height subsides and seismic alert clears) *)
        IF NOT bEnable AND NOT bSeismicAlert AND (rWaveHeightAvg_m < 1.0) THEN
            bLockEngageCommand := FALSE;
            bGateDeployCommand := FALSE;
            iState := 0; (* Return to idle / retract *)
        END_IF;

    99: (* FAULT STATE *)
        bSystemReady := FALSE;
        bGateDeployCommand := FALSE;
        bLockEngageCommand := FALSE;
        rTargetPressure_bar := 0.0;
        bCriticalAlarm := TRUE;

        (* Fault recovery requires emergency stop reset or manual intervention *)
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

iOperatingState := iState;

END_FUNCTION_BLOCK
